/**
 * Returns the sum of the digits of an integer.
 *
 * @param int $number The input integer
 * @return int Sum of its digits
 */
function sumOfDigits(int $number): int {
    $number = abs($number); // Ignore negative signs
    $sum = 0;

    while ($number > 0) {
        $sum += $number % 10;          // Add the last digit
        $number = intdiv($number, 10); // Remove the last digit
    }

    return $sum;
}
```

### 🔍 How it works:
